#!/usr/bin/env python3
# SPDX-License-Identifier: Apache-2.0
"""Render an already verified research cycle for local reading and export."""
import argparse,html,json
from pathlib import Path
import research_cycle as C

def fragment(root,expected):
 C.verify(root,expected);s=C.parse(C.read_regular(root,'summary.json'));p=C.packet(root,expected)
 rows=''.join('<tr data-cycle-state="'+html.escape(r['state'])+'"><td>'+html.escape(r['repo'])+'</td><td>'+html.escape(r['state'])+'</td><td>'+html.escape(r['next_action'].replace('_',' ').lower())+'</td></tr>' for r in s['queue'])
 data=json.dumps(p,ensure_ascii=False,separators=(',',':')).replace('<','\\u003c')
 return '''<style>
#researchEvidenceCycle{font:15px/1.55 system-ui,sans-serif;color:#203b34;margin:24px auto;padding:12px 22px;border:1px solid #cddbd4;border-radius:12px;background:#fbfcf8;max-width:1180px;box-sizing:border-box}#researchEvidenceCycle *{box-sizing:border-box}#researchEvidenceCycle summary{cursor:pointer;min-height:44px;font-weight:650;display:flex;align-items:center}#researchEvidenceCycle h2{font-size:26px;line-height:1.2;margin:15px 0}#researchEvidenceCycle p{font-size:13px;margin:12px 0;overflow-wrap:anywhere}#researchEvidenceCycle .cycle-stats{display:grid;grid-template-columns:repeat(3,minmax(0,1fr));gap:10px;margin:20px 0}#researchEvidenceCycle .cycle-stat{padding:16px;border:1px solid #d9e3dc;background:#fff;border-radius:8px}#researchEvidenceCycle .cycle-stat strong{display:block;font-size:30px;line-height:1.2}#researchEvidenceCycle .cycle-stat span{font-size:12px;color:#50645c}#researchEvidenceCycle .cycle-actions{display:flex;gap:8px;flex-wrap:wrap}#researchEvidenceCycle button{font:13px system-ui;min-height:44px;padding:10px 14px;border:1px solid #abc1b5;border-radius:7px;color:#203b34;background:#fff;cursor:pointer}#researchEvidenceCycle button:focus-visible,#researchEvidenceCycle input:focus-visible,#researchEvidenceCycle select:focus-visible{outline:3px solid #30785b;outline-offset:2px}#researchEvidenceCycle input,#researchEvidenceCycle select{font:13px system-ui;padding:12px;border:1px solid #b6c8bc;border-radius:6px;width:100%;min-width:0;background:#fff;color:#203b34}#researchEvidenceCycle label{display:block;font-size:12px;margin:12px 0}#researchEvidenceCycle .cycle-table{max-height:340px;overflow:auto;margin:14px 0}#researchEvidenceCycle table{border-collapse:collapse;width:100%;font-size:12px;table-layout:fixed}#researchEvidenceCycle th,#researchEvidenceCycle td{padding:10px;border-bottom:1px solid #dce4de;text-align:left;overflow-wrap:anywhere}#researchEvidenceCycle code{font-size:11px;overflow-wrap:anywhere}#researchEvidenceCycle .cycle-note{border-left:3px solid #b67d37;padding-left:12px;color:#775025}#researchEvidenceCycle [hidden]{display:none!important}@media(max-width:620px){#researchEvidenceCycle{padding:10px 14px}.cycle-stats{gap:6px!important}#researchEvidenceCycle .cycle-stat{padding:10px}#researchEvidenceCycle .cycle-stat strong{font-size:24px}}
</style><details id="researchEvidenceCycle"><summary>Evidence cycle · check, compare and reuse</summary><h2>Every check keeps its history.</h2><p>These are comparisons of recorded repository revisions. They identify changes that need review before reuse.</p><div class="cycle-stats"><div class="cycle-stat"><strong>'''+str(s['repository_count'])+'''</strong><span>repository observations</span></div><div class="cycle-stat"><strong>'''+str(s['state_counts'].get('DIVERGENT',0))+'''</strong><span>changed revisions</span></div><div class="cycle-stat"><strong>'''+str(s['prior_events_linked'])+'''</strong><span>links to earlier evidence</span></div></div><p><b>Evaluated:</b> '''+html.escape(s['as_of'])+''' · <b>Runtime tests of these repositories:</b> not run.</p><p class="cycle-note">A matching revision is not a safety or performance result. Older observations and failures remain retained. No policy, model or human approval is changed by this workflow.</p><div class="cycle-actions"><button type="button" data-cycle-download="packet">Download complete evidence</button><button type="button" data-cycle-download="events.jsonl">Native events</button><button type="button" data-cycle-download="evidence.sarif.json">SARIF export</button><button type="button" data-cycle-download="evaluation.otlp.json">OpenTelemetry export</button></div><label>Show observations<select id="cycleFilter"><option value="">All states</option><option>DIVERGENT</option><option>CONSISTENT</option><option>UNCHECKABLE</option><option>UNMEASURED</option></select></label><p id="cycleCount" role="status">'''+str(s['repository_count'])+''' observations</p><div class="cycle-table"><table><thead><tr><th>Repository</th><th>Evidence state</th><th>Next step</th></tr></thead><tbody>'''+rows+'''</tbody></table></div><details><summary>Check a downloaded evidence file</summary><p>Use the expected manifest digest from a trusted source. This browser checks the file bytes. The trusted Python receiver also reconstructs the event accounting and exports.</p><label>Expected manifest SHA-256<input id="cycleExpected" maxlength="64" value="'''+expected+'''" spellcheck="false"></label><label>Evidence JSON file<input id="cycleFile" type="file" accept=".json,application/json"></label><button id="cycleCheckFile" type="button">Check selected file</button><p id="cycleVerification" role="status">No file selected. No data is uploaded.</p></details><p><b>Manifest:</b> <code>'''+expected+'''</code></p><p>Unsigned local evidence. Publisher identity, independent review and execution authority are not established.</p></details><script id="researchCyclePacket" type="application/json">'''+data+r'''</script><script id="researchCycleScript">
(()=>{'use strict';const P=JSON.parse(document.getElementById('researchCyclePacket').textContent),$=id=>document.getElementById(id);const names=['catalogue.json','observations.json','binding.json','events.jsonl','summary.json','evaluation.otlp.json','evidence.sarif.json'].sort();
const hash=async text=>Array.from(new Uint8Array(await crypto.subtle.digest('SHA-256',new TextEncoder().encode(text))),x=>x.toString(16).padStart(2,'0')).join('');
for(const button of document.querySelectorAll('[data-cycle-download]'))button.addEventListener('click',()=>{const key=button.dataset.cycleDownload;const text=key==='packet'?JSON.stringify(P,null,2)+'\n':P.files[key];const url=URL.createObjectURL(new Blob([text],{type:'application/json'}));const a=document.createElement('a');a.href=url;a.download=key==='packet'?'Council_Research_Evidence_Cycle.json':key;document.body.append(a);a.click();a.remove();setTimeout(()=>URL.revokeObjectURL(url),1000);});
$('cycleFilter').addEventListener('change',()=>{let count=0;for(const row of document.querySelectorAll('[data-cycle-state]')){row.hidden=!!$('cycleFilter').value&&row.dataset.cycleState!==$('cycleFilter').value;if(!row.hidden)count++;}$('cycleCount').textContent=count+' observations';});
$('cycleCheckFile').addEventListener('click',async()=>{const out=$('cycleVerification'),file=$('cycleFile').files[0],expected=$('cycleExpected').value;out.textContent='Checking…';try{if(!file||file.size>8000000)throw Error('Select a JSON file smaller than 8 MB.');if(!/^[a-f0-9]{64}$/.test(expected))throw Error('A full expected SHA-256 is required.');const q=JSON.parse(await file.text());if(q.schema!=='csoai.research-cycle-download/0.1'||typeof q.manifest_text!=='string'||!q.files)throw Error('Unsupported evidence file.');if(await hash(q.manifest_text)!==expected)throw Error('Manifest does not match the expected digest.');const m=JSON.parse(q.manifest_text);if(JSON.stringify(Object.keys(m.files).sort())!==JSON.stringify(names)||JSON.stringify(Object.keys(q.files).sort())!==JSON.stringify(names))throw Error('Incomplete or unexpected files.');for(const n of names){if(typeof q.files[n]!=='string'||await hash(q.files[n])!==m.files[n].sha256||new TextEncoder().encode(q.files[n]).length!==m.files[n].bytes)throw Error('Changed file: '+n);}out.textContent='File bytes match the selected manifest. Use the Python receiver to recheck derived accounting. This does not authenticate the producer.';}catch(e){out.textContent='REJECTED: '+e.message;}});
})();</script>'''

def main():
 p=argparse.ArgumentParser(description=__doc__);p.add_argument('directory');p.add_argument('--expected-manifest',required=True);p.add_argument('--output',required=True);p.add_argument('--fragment',action='store_true');a=p.parse_args()
 body=fragment(a.directory,a.expected_manifest)
 out=body if a.fragment else '<!doctype html><html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Council of AI · Research evidence cycle</title></head><body style="margin:16px;background:#f3f6f1">'+body+'</body></html>'
 Path(a.output).write_text(out,encoding='utf-8')
if __name__=='__main__':main()
